class OrderStatusUpdater:
    def update_status(self, order: Order, status: str):
        order.status = status

class PaymentProcessor:
    def __init__(self, order_status_updater: OrderStatusUpdater):
        self.order_status_updater = order_status_updater

    def pay(self, order: Order, security_code: str):
        print("Processing payment")
        print(f"Verifying security code: {security_code}")
        self.order_status_updater.update_status(order, "paid")
